$(document).ready(function(){$("#processToPayment").click(function(e){e.preventDefault(),$("#processToPayment").hide();$("#couponCode").val();var a="default";0!=$("#orderType").length&&(a=$("#orderType").val());var o="default";0!=$("#app").length&&(o=$("#app").val());var n=$(".shipping-box").serializeArray();n.push({name:"type",value:"order"}),n.push({name:"action",value:"generate"}),n.push({name:"order",value:$("#orderId").val()}),n.push({name:"app",value:o}),n.push({name:"pgRequestType",value:a}),n.push({name:"paymentMode",value:$("#paymentMode").val()}),$.ajax({type:"POST",dataType:"json",data:n,success:function(e){200==e.status?window.location.href=e.url:console.log("Success : ",e),$("#processToPayment").show()},error:function(e){console.log("error : ",e),$("#processToPayment").show()}})})});